import React from 'react';
import DraggableResizable from './DraggableResizable';

const VideoPlayer = ({ videoId, settings, onResizeStop, onDragStop }) => {
  const videoSrc = `https://www.youtube.com/embed/${videoId}`;

  return (
    <DraggableResizable
      defaultWidth={settings.width}
      defaultHeight={settings.height}
      defaultX={settings.x}
      defaultY={settings.y}
      onResizeStop={(e, { size }) => onResizeStop(size)}
      onDragStop={(e, { x, y }) => onDragStop({ x, y })}
    >
      <div className="video-container" style={{ width: '100%', height: '100%' }}>
        <iframe
          width="100%"
          height="100%"
          src={videoSrc}
          frameBorder="0"
          allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
          title="Video Player"
        ></iframe>
      </div>
    </DraggableResizable>
  );
};

export default VideoPlayer;
